import numpy as np
import mobileranker as mr

def get_observation():
    return mr.get_observation()
def segment_sam3_text_prompt(rgb, prompt):
    return mr.segment_sam3_text_prompt(rgb, prompt)
def get_3d_points(prompt_mask, depth, intr):
    return mr.get_3d_points(prompt_mask, depth, intr)
def get_oriented_bounding_box_from_3d_points(pts):
    return mr.get_oriented_bounding_box_from_3d_points(pts)
def getf():
    return mr.get_finger_positions()
def solve_ik(target, quat):
    return mr.solve_ik(target, quat)
def move_to_joints(j):
    return mr.move_to_joints(j)
def open_gripper():
    return mr.open_gripper()
def close_gripper():
    return mr.close_gripper()

def seg_obb(obs, prompt):
    rgb=obs['rgb']; depth=obs['depth']; intr=obs['intrinsics']
    m=segment_sam3_text_prompt(rgb, prompt)
    if m is None or int(m.sum())<30: return None
    pts=get_3d_points(m, depth, intr)
    if pts is None or len(pts)<10: return None
    obb=get_oriented_bounding_box_from_3d_points(pts)
    return obb['center'], obb['extents'], obb['rotation']

def quat2mat(q):
    w,x,y,z=q
    return np.array([[1-2*(y*y+z*z), 2*(x*y-w*z), 2*(x*z+w*y)],
                     [2*(x*y+w*z), 1-2*(x*x+z*z), 2*(y*z-w*x)],
                     [2*(x*z-w*y), 2*(y*z+w*x), 1-2*(x*x+y*y)]])
def mat2quat(R):
    tr=R[0,0]+R[1,1]+R[2,2]
    if tr>0:
        S=2.0*(tr+1.0)**0.5; w=0.25*S; x=(R[2,1]-R[1,2])/S; y=(R[0,2]-R[2,0])/S; z=(R[1,0]-R[0,1])/S
    elif R[0,0]>R[1,1] and R[0,0]>R[2,2]:
        S=2.0*(1.0+R[0,0]-R[1,1]-R[2,2])**0.5; w=(R[2,1]-R[1,2])/S; x=0.25*S; y=(R[0,1]+R[1,0])/S; z=(R[0,2]+R[2,0])/S
    elif R[1,1]>R[2,2]:
        S=2.0*(1.0+R[1,1]-R[0,0]-R[2,2])**0.5; w=(R[0,2]-R[2,0])/S; x=(R[0,1]+R[1,0])/S; y=0.25*S; z=(R[1,2]+R[2,1])/S
    else:
        S=2.0*(1.0+R[2,2]-R[0,0]-R[1,1])**0.5; w=(R[1,0]-R[0,1])/S; x=(R[0,2]+R[2,0])/S; y=(R[1,2]+R[2,1])/S; z=0.25*S
    return np.array([w,x,y,z])
def align_rot(axis):
    axis=axis/(np.linalg.norm(axis)+1e-9)
    target=np.array([0.0,0.0,1.0])
    v=np.cross(axis,target); s=np.linalg.norm(v); c=float(np.dot(axis,target))
    if s<1e-6:
        return np.eye(3) if c>0 else np.diag([1.0,-1.0,-1.0])
    v=v/s
    vx=np.array([[0.0,-v[2],v[1]],[v[2],0.0,-v[0]],[-v[1],v[0],0.0]])
    return np.eye(3)+vx+(vx@vx)*(1.0-c)/(s*s)

obs=get_observation()
h=seg_obb(obs, "extruded handle of the brown square nut")
cnt=seg_obb(obs, "white hollow center of the brown square nut")
bl=seg_obb(obs, "brown square block")
if h is None or cnt is None or bl is None:
    raise ValueError("seg failed")
ch,e_h,Rh=h
cn,e_c,Rc=cnt
cb,e_b,Rb=bl

# side/long-axis grasp of the handle (iq=maxf): approach from the handle's long side at handle height
iq=int(np.argmax(e_h))
f=float(e_h[iq]); off=max(0.10, f/2.0+0.06)
tp=ch.copy(); tp[iq]+=off
q0=np.array([1.0,0.0,0.0,0.0])
open_gripper()
appro=max(0.10, max(0.06, e_h[int(np.argmin(e_h))]/2.0+0.04)+0.08)
tap=tp.copy(); tap[2]+=appro
move_to_joints(solve_ik(tap+np.array([0.0,0.0,0.10]), q0))
move_to_joints(solve_ik(tap, q0))
move_to_joints(solve_ik(tp, q0))
close_gripper()
lift=tp.copy(); lift[2]+=0.20
move_to_joints(solve_ik(lift, q0))

# reorient: nut hole axis vertical
hole_axis=Rc[:, int(np.argmin(e_c))]
D=align_rot(hole_axis)
q1=mat2quat(D @ quat2mat(q0))
move_to_joints(solve_ik(lift, q1))

# re-observe nut center + block; align center over block, lower to insert
obs2=get_observation()
cnt2=seg_obb(obs2, "white hollow center of the brown square nut")
bl2=seg_obb(obs2, "brown square block")
cn2=cnt2[0] if cnt2 else cn
cb2=bl2[0] if bl2 else cb
above=np.array([cb2[0], cb2[1], cb2[2]+0.10], dtype=float)
move_to_joints(solve_ik(above, q1))
place=np.array([cb2[0], cb2[1], cb2[2]+0.02], dtype=float)
move_to_joints(solve_ik(place, q1))
open_gripper()

